import React from 'react';
import { ComponentMeta, ComponentStory } from '@storybook/react';
import { ProgressTracker, Paragraph } from '../../../../../..';

export default {
  title: 'General/ProgressTracker/Step',
  component: ProgressTracker.Step,
  argTypes: {
    index: {
      description:
        'The position of the step(zero based index). The index number showed on the cicle button is `index + 1.`',
    },
    completed: {
      description: 'Mark the step as completed. Is passed to child components.',
      defaultValue: false,
    },
    disabled: {
      description: 'Mark the step as disabled. Is passed to child components.',
      defaultValue: false,
    },
    error: {
      description: 'Mark the step as with error. Is passed to child components.',
      defaultValue: false,
    },
    children: {
      description: 'Should be Step sub-component `StepLabel` or a custom ReactNode.',
    },
    onSelect: {
      description: 'Event handler called when the step is clicked.',
    },
  },
  parameters: {
    docs: {
      description: {
        component:
          'The `ProgressTracker.Step` component should be used as a subcomponent of the `ProgressTracker.Header`. <br>The `ProgressTracker.Step` should be used with `ProgressTracker.StepLabel` or a ReactNode as subcomponents.<br><br>How to install: `yarn add @hexa-ui/components`<br><br>How to import: `import { ProgressTracker } from "@hexa-ui/components"`<br><br>How to use: `ProgressTracker.Step` or destructure it `{ Step } = ProgressTracker`',
      },
    },
  },
} as ComponentMeta<typeof ProgressTracker.Step>;

const Template: ComponentStory<typeof ProgressTracker.Step> = (args) => (
  <ProgressTracker.Root>
    <ProgressTracker.Header>
      <ProgressTracker.Step {...args} />
    </ProgressTracker.Header>
  </ProgressTracker.Root>
);

export const step = Template.bind({});

export const stepCompleted = Template.bind({});
stepCompleted.args = {
  completed: true,
};

export const stepError = Template.bind({});
stepError.args = {
  error: true,
};

export const stepDisabled = Template.bind({});
stepDisabled.args = {
  disabled: true,
};

export const stepWithStepLabelChildren = (args) => (
  <ProgressTracker.Root>
    <ProgressTracker.Header>
      <ProgressTracker.Step {...args}>
        <ProgressTracker.StepLabel label="Step 1" detail="Detail" />
      </ProgressTracker.Step>
    </ProgressTracker.Header>
  </ProgressTracker.Root>
);

export const stepWithCustomChildren = (args) => (
  <ProgressTracker.Root>
    <ProgressTracker.Header>
      <ProgressTracker.Step {...args}>
        <Paragraph>Custom Children</Paragraph>
      </ProgressTracker.Step>
    </ProgressTracker.Header>
  </ProgressTracker.Root>
);

export const stepWithOnSelectHandler = Template.bind({});
stepWithOnSelectHandler.args = {
  onSelect: (indexSelected) => alert(`Step ${indexSelected} `),
};
